update soal set bab = '01 · フロント業務 (resepsionis)', halaman = 20, kalimat = '必ずドアをノックするか呼び鈴を鳴らし、お客様が「入ってください」という許可をもらってから客室に入らなければいけません。', kalimat_ruby = null, kosakata = '[]'::jsonb where kategori = '宿泊分野' and urutan = 5;
