update soal set bab = '01 · フロント業務 (resepsionis)', halaman = 19, kalimat = 'お客様がご滞在中にフロントに電話があった際は、話している内容が聞き取りやすいように、はっきりとゆっくり話すよう心がけます。', kalimat_ruby = null, kosakata = '[]'::jsonb where kategori = '宿泊分野' and urutan = 7;
update soal set bab = '01 · フロント業務 (resepsionis)', halaman = 22, kalimat = 'D. 遺失物（忘れ物）の保管', kalimat_ruby = null, kosakata = '[]'::jsonb where kategori = '宿泊分野' and urutan = 8;
