update soal set bab = '03 · 接客 (layanan tamu)', halaman = 38, kalimat = '約30°前傾・敬礼（普通礼）：お客様をお迎えする時をはじめとして、様々な場面で最も使います。', kalimat_ruby = null, kosakata = '[]'::jsonb where kategori = '宿泊分野' and urutan = 10;
update soal set bab = '03 · 接客 (layanan tamu)', halaman = 40, kalimat = '宿泊施設内でお客様をご案内する際には、2～3歩、左前方を、お客様の歩調に合わせながら歩きます。', kalimat_ruby = null, kosakata = '[]'::jsonb where kategori = '宿泊分野' and urutan = 11;
update soal set bab = '01 · フロント業務 (resepsionis)', halaman = 40, kalimat = 'ルームキーをお客様に渡す時には、相手から見て正面の方向に向けて両手でお渡しします。', kalimat_ruby = null, kosakata = '[]'::jsonb where kategori = '宿泊分野' and urutan = 12;
update soal set bab = '03 · 接客 (layanan tamu)', halaman = 42, kalimat = 'クレーム対応のポイントは、まず不快にさせたことをお詫びする・クレームの原因を丁寧に確認する・責任者に報告することです。', kalimat_ruby = null, kosakata = '[]'::jsonb where kategori = '宿泊分野' and urutan = 13;
