update soal set bab = '01 · フロント業務 (resepsionis)', halaman = 22, kalimat = 'KPI として設定されるADR、RevPAR、OCC（客室稼働率）のほか、費用である人件費、消耗品費、客室の販売手数料などについてしっかりと把握しておく必要があります。', kalimat_ruby = null, kosakata = '[]'::jsonb where kategori = '宿泊分野' and urutan = 15;
update soal set bab = '05 · 安全衛生管理・その他', halaman = 61, kalimat = '火災を発見した場合は、速やかに初期消火を実施し、お客様を安全に避難させる。', kalimat_ruby = null, kosakata = '[]'::jsonb where kategori = '宿泊分野' and urutan = 16;
update soal set bab = '05 · 安全衛生管理・その他', halaman = 61, kalimat = '火災や地震が発生した場合は、絶対にエレベーターを使用せず、非常階段…', kalimat_ruby = null, kosakata = '[]'::jsonb where kategori = '宿泊分野' and urutan = 17;

select urutan, bab, halaman from soal where kategori = '宿泊分野' order by urutan;

