-- ================================================
-- picto-gambar.sql
-- ================================================
-- soal bergambar papan tanda: jawaban = istilah Jepang (kanji), bukan arti Indonesia
alter table soal add column if not exists gambar text;
alter table kosakata add column if not exists gambar text;

update kosakata set gambar = case kanji
  when '案内所' then 'aset/picto/001.png'
  when '病院' then 'aset/picto/002.png'
  when '救護所' then 'aset/picto/003.png'
  when '警察' then 'aset/picto/004.png'
  when 'お手洗' then 'aset/picto/005.png'
  when '男性' then 'aset/picto/006.png'
  when '女性' then 'aset/picto/007.png'
  when '障害のある人が使える設備' then 'aset/picto/008.png'
  when 'スロープ' then 'aset/picto/009.png'
  when '飲料水' then 'aset/picto/010.png'
  when '喫煙所' then 'aset/picto/011.png'
  when '加熱式たばこ専用喫煙室' then 'aset/picto/012.png'
  when 'チェックイン' then 'aset/picto/013.png'
  when '忘れ物取扱所' then 'aset/picto/014.png'
  when 'ホテル' then 'aset/picto/015.png'
  when 'きっぷうりば' then 'aset/picto/016.png'
  when '手荷物一時預かり所' then 'aset/picto/017.png'
  when 'コインロッカー' then 'aset/picto/018.png'
  when '休憩所' then 'aset/picto/019.png'
  when 'ミーティングポイント' then 'aset/picto/020.png'
  when '銀行・両替' then 'aset/picto/021.png'
  when 'キャッシュサービス' then 'aset/picto/022.png'
  when '郵便' then 'aset/picto/023.png'
  when '電話' then 'aset/picto/024.png'
  when 'ファックス' then 'aset/picto/025.png'
  when 'カート' then 'aset/picto/026.png'
  when 'エレベーター' then 'aset/picto/027.png'
