-- ================================================
-- perbaikan-sumber.sql
-- ================================================
-- perbaikan: baris ピクトグラム & 制度 pernah kena update soal 2号 (bug sumber-soal.sql)
update soal set sumber_pdf = 'picto', bab = 'ピクトグラム', halaman = null,
                 kalimat = null, kalimat_ruby = null, kosakata = '[]'::jsonb
 where kategori = 'ピクトグラム';

update soal set sumber_pdf = null, bab = null, halaman = null,
                 kalimat = null, kalimat_ruby = null, kosakata = '[]'::jsonb
 where kategori = '制度';

-- seragamkan label PDF bab 宿泊 (2号)
update soal set sumber_pdf = '2号' where kategori = '宿泊分野' and sumber_pdf = '宿泊分野';

-- hapus soal yang pertanyaannya sama dalam kategori yang sama
delete from soal a using soal b
 where a.id > b.id and a.kategori = b.kategori and a.pertanyaan = b.pertanyaan
   and a.kategori <> 'ピクトグラム';

-- audit: semua harus 0
select 'picto punya halaman' as masalah, count(*) as baris
  from soal where kategori = 'ピクトグラム' and halaman is not null
union all select 'picto sumber salah', count(*) from soal where kategori = 'ピクトグラム' and coalesce(sumber_pdf,'') <> 'picto'
union all select '制度 sumber terisi', count(*) from soal where kategori = '制度' and sumber_pdf is not null
union all select '2号 tanpa halaman', count(*) from soal where kategori = '宿泊分野' and halaman is null
union all select '1号 tanpa halaman', count(*) from soal where kategori = '宿泊分野（1号）' and halaman is null
union all select 'bab tak cocok materi', count(*) from soal s
   where s.bab is not null and s.kategori <> 'ピクトグラム'
     and not exists (select 1 from materi m where m.judul = s.bab);

-- ================================================
-- belajar.sql
-- ================================================
-- progres belajar per hari & sesi (30 hari x 3 sesi)
create table if not exists progres (
  id      bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  hari    int  not null check (hari between 1 and 30),
  sesi    text not null check (sesi in ('materi','pagi','pagi1','pagi2','pagi3','siang','malam')),
  skor    int,
  total   int,
  selesai timestamptz not null default now(),
  unique (user_id, hari, sesi)
);

alter table progres enable row level security;
drop policy if exists progres_baca on progres;
drop policy if exists progres_baca on progres;
create policy progres_baca on progres for select to authenticated using (auth.uid() = user_id);
drop policy if exists progres_tulis on progres;
drop policy if exists progres_tulis on progres;
create policy progres_tulis on progres for insert to authenticated with check (auth.uid() = user_id);
drop policy if exists progres_ubah on progres;
drop policy if exists progres_ubah on progres;
create policy progres_ubah on progres for update to authenticated using (auth.uid() = user_id);

-- ================================================
-- sesi-pagi.sql
-- ================================================
-- perbaikan: constraint lama menolak baris lama (sesi 'pagi')
alter table progres drop constraint if exists progres_sesi_check;

-- baris lama 'pagi' -> jadi 'pagi1'
update progres set sesi = 'pagi1' where sesi = 'pagi';

alter table progres add constraint progres_sesi_check
  check (sesi in ('materi','pagi','pagi1','pagi2','pagi3','siang','malam'));

alter table progres add column if not exists waktu_ms int;
alter table progres add column if not exists jumlah_soal int;

-- ================================================
-- riwayat.sql
-- ================================================
-- riwayat jawaban (untuk sesi malam: soal hari sebelumnya ikut masuk)
create table if not exists riwayat (
  id      bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  hari    int not null,
  sesi    text not null,
  soal_id bigint,
  benar   boolean not null default false,
  dibuat  timestamptz not null default now(),
  unique (user_id, hari, sesi, soal_id)
);

alter table riwayat enable row level security;

drop policy if exists riwayat_baca on riwayat;
create policy riwayat_baca on riwayat for select to authenticated using (auth.uid() = user_id);

drop policy if exists riwayat_tulis on riwayat;
create policy riwayat_tulis on riwayat for insert to authenticated with check (auth.uid() = user_id);

drop policy if exists riwayat_ubah on riwayat;
create policy riwayat_ubah on riwayat for update to authenticated using (auth.uid() = user_id);

-- ================================================
-- perbaikan-materi.sql
-- ================================================
-- perbaikan: teks materi berisi "\n" literal, ganti jadi baris baru sungguhan
update materi set isi = replace(isi, '\n', chr(10)) where isi like '%\n%';
update materi set ringkas = replace(ringkas, '\n', ' ') where ringkas like '%\n%';
select judul, length(isi) as panjang from materi order by urutan;

-- ================================================
-- rapikan.sql
-- ================================================
-- rapikan: hapus baris dobel (kalau skrip pernah dijalankan 2x)
delete from materi a using materi b
  where a.id > b.id and a.kategori = b.kategori and a.judul = b.judul;

delete from kosakata a using kosakata b
  where a.id > b.id and a.kanji = b.kanji and a.kana = b.kana and a.level = b.level;

-- soal: kolom level tidak ada; pembanding pakai pertanyaan + sumber + gambar + pilihan
delete from soal a using soal b
  where a.id > b.id
    and a.pertanyaan = b.pertanyaan
    and coalesce(a.sumber_pdf,'') = coalesce(b.sumber_pdf,'')
    and coalesce(a.gambar,'') = coalesce(b.gambar,'')
    and a.pilihan::text = b.pilihan::text;

select 'materi' as tabel, count(*)::text as jumlah from materi
union all select 'kosakata', count(*)::text from kosakata
union all select 'soal', count(*)::text from soal;
commit;
select 'soal 2号' as t, count(*)::text from soal where kategori='宿泊分野'
union all select 'soal 1号', count(*)::text from soal where kategori='宿泊分野（1号）'
union all select 'soal picto', count(*)::text from soal where sumber_pdf='picto';
